package com.refresh165;
import java.util.*;
/** Strict wire format: package=f165/v120/follow/system. Unknown data never forces a rate. */
final class AppProfiles {
 static final class Rule {final String mode;final int rate;Rule(String m,int n){mode=m;rate=n;}boolean fixed(){return mode.equals("f");}boolean explicit(){return mode.equals("f")||mode.equals("v")||mode.equals("follow");}String wire(){return explicit()&&!mode.equals("follow")?mode+rate:mode;}}
 static boolean packageName(String p){return p!=null&&p.length()<=255&&p.matches("[A-Za-z_][A-Za-z0-9_]*(?:\\.[A-Za-z_][A-Za-z0-9_]*)+");}
 static Rule rule(String value){if(value==null)return null;if(value.equals("follow")||value.equals("system"))return new Rule(value,0);if(value.length()<3||!(value.charAt(0)=='f'||value.charAt(0)=='v'))return null;try{int n=Integer.parseInt(value.substring(1));if(!(n==60||n==90||n==120||n==144||n==165)||!value.equals(value.charAt(0)+String.valueOf(n)))return null;return new Rule(value.substring(0,1),n);}catch(Exception e){return null;}}
 static Map<String,Rule> parse(String text){Map<String,Rule> out=new TreeMap<>();if(text==null||text.length()>200000)return out;for(String line:text.split(";")){int i=line.indexOf('=');if(i<=0)continue;String p=line.substring(0,i);Rule r=rule(line.substring(i+1));if(packageName(p)&&r!=null)out.put(p,r);}return out;}
 static String encode(Map<String,Rule> entries){StringBuilder out=new StringBuilder();for(Map.Entry<String,Rule> e:new TreeMap<>(entries).entrySet()){if(!packageName(e.getKey())||e.getValue()==null)throw new IllegalArgumentException("Invalid application profile");if(out.length()>0)out.append(';');out.append(e.getKey()).append('=').append(e.getValue().wire());}if(out.length()>200000)throw new IllegalArgumentException("Too many application profiles");return out.toString();}
 static String update(String old,String packages,String value){Rule r=rule(value);if(r==null)throw new IllegalArgumentException("Invalid refresh policy");if(packages==null||packages.length()>200000)throw new IllegalArgumentException("Invalid package list");Map<String,Rule> all=parse(old);String[] ids=packages.split(";",-1);if(ids.length==0||ids.length>10000)throw new IllegalArgumentException("Invalid package count");for(String p:ids){if(!packageName(p))throw new IllegalArgumentException("Invalid package name");all.put(p,r);}return encode(all);}
}
